def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            if r > start:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_seps = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    col_bands = []
    start = 0
    for c in col_seps:
        if c > start:
            col_bands.append((start, c))
        start = c + 1
    if start < w:
        col_bands.append((start, w))
    return [[1 if sum(grid[r][c] == 8 for r in range(a,b) for c in range(x,y)) == 2 else 5 for x,y in col_bands] for a,b in row_bands]
